const input = $input.all();
const normalized = [];

function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash |= 0;
  }
  return 'post_' + Math.abs(hash).toString(36);
}

for (const entry of input) {
  const data = entry.json || {};
  const rawItems = Array.isArray(data.organic)
    ? data.organic
    : (Array.isArray(data.items) ? data.items : []);

  for (const it of rawItems) {
    const link = (it.link || '').trim();
    if (!link) continue;

    const postId = simpleHash(link);
    const title = (it.title || '').trim();
    const snippet = (it.snippet || '').trim();
    const sourceDomain = (it.displayLink || it.domain || '').replace(/^https?:\/\//, '');

    const content = `${title} ${snippet}`.trim();

    normalized.push({
      json: {
        postId,
        title,
        snippet,
        content,
        link,
        authorName: sourceDomain || 'Nguồn không xác định',
        postUrl: link,
        sourceDomain
      }
    });
  }
}

return normalized;

const items = $input.all();

// Smock: bỏ bài phía NGƯỜI BÁN, tuyển dụng, đồ cũ. Bài vượt qua vẫn được LLM chấm lại.
const negativeKeywords = [
  'we manufacture', 'our factory', 'we are a manufacturer', 'we are a supplier', 'supplier here',
  'we offer wholesale', 'dm for price', 'pm for price', 'now accepting orders', 'shop our', 'use code',
  'hiring', 'job opening', 'we are hiring', 'giveaway',
  'preloved', 'pre-loved', 'destash', 'gently used', 'nwt', 'iso size'
];

const norm = s => (s || '').toString().toLowerCase();
return items.filter(item => {
  const p = item.json || {};
  const text = norm(p.content || `${p.title || ''} ${p.snippet || ''}`);
  return !negativeKeywords.some(kw => text.includes(kw));
});

// Input chính = 100 bài viết mới (đến từ Pre-Filter Negative Keywords)
const newPosts = $input.all();

// Lấy danh sách post_id đã scan từ node Postgres — tham chiếu trực tiếp theo tên node,
// không cần node đó nối input vào đây, chỉ cần nó đã chạy trước trong cùng execution
let scannedRows = [];
try {
  scannedRows = $('Postgres - Get Already Scanned Post IDs').all();
} catch (err) {
  scannedRows = [];
}

const scannedIds = new Set(
  scannedRows
    .map(row => row.json.post_id)
    .filter(id => id !== undefined && id !== null)
);

// Lọc: chỉ giữ lại bài chưa từng scan
const result = newPosts.filter(item => !scannedIds.has(item.json.postId));

return result;

const item = $input.item.json;

const systemPrompt = `You classify public posts for K-Embroidery, a Vietnam factory that makes hand-smocked children's clothing for boutiques and online shops (wholesale, OEM/private label, MOQ 15 pieces per design, free 2D mock-ups).

Your input contains ONLY a search-result title and snippet. Classify only what the visible text supports. Do not invent hidden context.

CLASSIFICATIONS
HIGH_INTENT = a business buyer (boutique, online shop, brand, reseller) is actively looking for a supplier, vendor, manufacturer or wholesale source of smocked / hand-embroidered children's clothing, or asks for recommendations for one. Examples: "looking for a smocked vendor for my boutique", "who makes your smocked dresses?", "ISO wholesale smocked supplier", "need a manufacturer for my smocked line", "any good private label smocking factory?".
LOW_INTENT = general discussion, a consumer buying 1-2 pieces for their own child, reviews, styling, or a mention of smocked clothing without a visible intent to source wholesale.
SPAM_SEEDING = seller/vendor/factory promoting itself, resale of used items, giveaways, recruitment, or other supply-side content.

IMPORTANT EDGE RULES
1. A parent buying for their own child is LOW_INTENT, not HIGH_INTENT.
2. If text contains both buyer and seller language, choose SPAM_SEEDING only when it is primarily offering goods.
3. Confidence measures evidence strength in the visible snippet, not general model certainty.

Return STRICT JSON ONLY with EXACTLY these 4 keys, nothing else, no markdown fences, no explanation:
{
  "classification": "HIGH_INTENT|LOW_INTENT|SPAM_SEEDING",
  "buyer_signal": true,
  "seller_signal": false,
  "confidence_score": 0.0
}`;

const userContent = `TITLE: ${item.title || ''}\nSNIPPET: ${item.snippet || ''}`;

// V6 FIX: 'nex-agi/nex-n2.5-mini:free' la model duy nhat thuc su tra loi (2 model Gemma
// truoc no gan nhu luon 404/unavailable nen OpenRouter fallback thang xuong no), va no
// la reasoning model -> voi max_tokens=120 no dung het budget cho phan "suy nghi" roi bi
// cat cut truoc khi kip xuat JSON => "Model response was not valid JSON" tren 100% item.
// Fix: dùng openrouter/free (auto-router, tu chon model con dang song VA ho tro structured
// output/json_object that su), tang max_tokens de co cho reasoning + JSON, va tat reasoning
// visible content de khong ngon token vao phan suy nghi.
const modelPool = [
  'openrouter/free',
  'google/gemma-4-31b-it:free',
  'nex-agi/nex-n2.5-mini:free'
];

const payload = {
  models: modelPool,
  temperature: 0,
  max_tokens: 7000,
  response_format: { type: 'json_object' },
  reasoning: { effort: 'low', exclude: true },
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userContent }
  ]
};

return {
  json: {
    ...item,
    requestBody: JSON.stringify(payload)
  }
};

const response = $input.item.json;
const original = $('Build LLM Request Payload').item.json;

const apiError = response.error?.message || response.message || null;
let parsed = null;
let parseErrorMsg = null;

// V5: robust content reader - handles string, array-of-parts, and objects
// that some OpenRouter providers return even when a string was expected.
// This fixes the "[object Object]" -> JSON.parse crash bug from V4.
function contentToRaw(content) {
  if (content === null || content === undefined) return '';
  if (typeof content === 'string') return content;
  if (Array.isArray(content)) {
    return content
      .map((part) => {
        if (typeof part === 'string') return part;
        if (part && typeof part.text === 'string') return part.text;
        return '';
      })
      .join('');
  }
  if (typeof content === 'object') {
    // Some providers already hand back a parsed object instead of a string.
    if ('classification' in content) return content; // already usable as-is
    try { return JSON.stringify(content); } catch { return ''; }
  }
  return String(content);
}

function extractJson(raw) {
  if (raw === null || raw === undefined || raw === '') return null;
  if (typeof raw === 'object' && !Array.isArray(raw)) return raw; // already parsed
  const cleaned = String(raw).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '');
  try { return JSON.parse(cleaned); } catch {}
  const first = cleaned.indexOf('{');
  const last = cleaned.lastIndexOf('}');
  if (first >= 0 && last > first) {
    try { return JSON.parse(cleaned.slice(first, last + 1)); } catch {}
  }
  return null;
}

let debugRaw = '';
if (!apiError) {
  const rawContent = response.choices?.[0]?.message?.content;
  const raw = contentToRaw(rawContent);
  debugRaw = typeof raw === 'string' ? raw.slice(0, 300) : JSON.stringify(raw).slice(0, 300);
  parsed = extractJson(raw);
  if (!parsed) parseErrorMsg = `Model response was not valid JSON | raw: ${debugRaw || '(empty)'}`;
}

const allowed = new Set(['HIGH_INTENT', 'LOW_INTENT', 'SPAM_SEEDING']);
const classification = String(parsed?.classification || '').trim().toUpperCase();
const isValid = !apiError && allowed.has(classification);

const confidence = Number(parsed?.confidence_score);
const safeConfidence = Number.isFinite(confidence) ? Math.max(0, Math.min(1, confidence)) : 0;

return {
  json: {
    postId: original.postId,
    authorName: original.authorName,
    postUrl: original.postUrl,
    title: original.title,
    snippet: original.snippet,
    content: original.content,
    sourceDomain: original.sourceDomain,
    classification: isValid ? classification : (apiError ? 'API_ERROR' : 'PARSE_ERROR'),
    buyer_signal: isValid ? parsed.buyer_signal === true : false,
    seller_signal: isValid ? parsed.seller_signal === true : false,
    confidence_score: isValid ? safeConfidence : 0,
    classifier_error: isValid ? null : (apiError || parseErrorMsg || 'Unknown classifier failure'),
    classifier_model_used: response.model || 'unknown',
    scan_ok: isValid
  }
};

