// Truy vấn tiếng Anh: chủ boutique / shop online ở US-EU đang tìm xưởng smock.
// Chỉ tìm bài CÔNG KHAI đã được Google index. Group kín không hiện ở đây, và workflow không cố vào.
const queries = [
  {
    "q": "site:facebook.com \"looking for\" smocked dresses supplier"
  },
  {
    "q": "site:facebook.com \"ISO\" smocked wholesale vendor"
  },
  {
    "q": "site:facebook.com \"recommend\" smocked clothing manufacturer"
  },
  {
    "q": "site:facebook.com \"who makes\" smocked dresses boutique"
  },
  {
    "q": "\"smocked\" \"wholesale\" \"looking for a vendor\""
  },
  {
    "q": "\"smocked\" \"manufacturer\" boutique owner recommendation"
  },
  {
    "q": "site:reddit.com smocked dresses supplier boutique"
  },
  {
    "q": "site:reddit.com children's boutique wholesale smocked vendor"
  },
  {
    "q": "\"hand smocked\" \"private label\" manufacturer looking"
  },
  {
    "q": "\"smocked\" \"Easter\" OR \"Valentine\" collection vendor boutique wholesale"
  }
];

return queries.map(item => ({ json: item }));

const item = $input.item.json;

const systemPrompt = `This public search snippet is a HIGH_INTENT lead: a business looking for a supplier of smocked children's clothing. Extract outreach details strictly from the visible TITLE and SNIPPET. Never invent facts; use null where the text does not say. Do NOT extract phone numbers or email addresses.

Facts about K-Embroidery you may use in the reply: Vietnam factory since 1996, hand-smocked and embroidered kids' clothing, wholesale and OEM/private label, MOQ 15 pieces per design, free 2D mock-ups, ships worldwide. Do not promise prices, delivery dates or anything else.

Return STRICT JSON ONLY with EXACTLY these 6 keys, no markdown fences, no explanation:
{
  "service_required": "what they want to source (e.g. 'smocked Easter dresses', 'private label smocked line') or null",
  "pain_point": "the buyer's stated need or problem, or null",
  "buyer_type": "boutique|online_shop|brand|reseller|unknown",
  "quantity_or_deadline": "quantity, sizes or deadline if literally stated, else null",
  "suggested_angle": "a short, honest English reply (max 3 sentences) a K-Embroidery salesperson could post or send, introducing themselves as K-Embroidery, answering their need, and asking when they need the goods. No pressure, no fake claims.",
  "intent_reason": "1 concise Vietnamese sentence explaining why this snippet shows buying intent"
}`;

const userContent = `TITLE: ${item.title || ''}\nSNIPPET: ${item.snippet || ''}`;

const modelPool = [
  'google/gemma-4-26b-a4b-it:free',
  'google/gemma-4-31b-it:free',
  'nex-agi/nex-n2.5-mini:free'
];

const payload = {
  models: modelPool,
  temperature: 0.2,
  max_tokens: 500,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userContent }
  ]
};

return {
  json: {
    ...item,
    extractionRequestBody: JSON.stringify(payload)
  }
};

const response = $input.item.json;
const original = $('Build Lead Extraction Payload').item.json;

const apiError = response.error?.message || response.message || null;
let parsed = null;

function contentToRaw(content) {
  if (content === null || content === undefined) return '';
  if (typeof content === 'string') return content;
  if (Array.isArray(content)) {
    return content
      .map((part) => {
        if (typeof part === 'string') return part;
        if (part && typeof part.text === 'string') return part.text;
        return '';
      })
      .join('');
  }
  if (typeof content === 'object') {
    if ('intent_reason' in content) return content;
    try { return JSON.stringify(content); } catch { return ''; }
  }
  return String(content);
}

function extractJson(raw) {
  if (raw === null || raw === undefined || raw === '') return null;
  if (typeof raw === 'object' && !Array.isArray(raw)) return raw;
  const cleaned = String(raw).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '');
  try { return JSON.parse(cleaned); } catch {}
  const first = cleaned.indexOf('{');
  const last = cleaned.lastIndexOf('}');
  if (first >= 0 && last > first) {
    try { return JSON.parse(cleaned.slice(first, last + 1)); } catch {}
  }
  return null;
}

if (!apiError) {
  parsed = extractJson(contentToRaw(response.choices?.[0]?.message?.content));
}

// Extraction failing must NEVER drop a real lead - fall back to safe placeholders
// so the Telegram alert / Postgres insert still go through with what we know.
return {
  json: {
    postId: original.postId,
    authorName: original.authorName,
    postUrl: original.postUrl,
    title: original.title,
    snippet: original.snippet,
    content: original.content,
    sourceDomain: original.sourceDomain,
    classification: original.classification,
    buyer_signal: original.buyer_signal,
    seller_signal: original.seller_signal,
    confidence_score: original.confidence_score,
    scan_ok: original.scan_ok,
    service_required: parsed?.service_required ?? null,
    pain_point: parsed?.pain_point ?? null,
    buyer_type: parsed?.buyer_type ?? 'unknown',
    quantity_or_deadline: parsed?.quantity_or_deadline ?? null,
    contact_phone: null, // Smock: không thu SĐT/email; Sale lấy khi khách tự liên hệ
    suggested_angle: parsed?.suggested_angle || 'Hi! This is K-Embroidery, a hand-smocked kids clothing factory in Vietnam (MOQ 15/design, free 2D mock-ups). Happy to share our catalog - when do you need the goods?',
    intent_reason: parsed?.intent_reason || 'Bài viết đang tìm nhà cung cấp hàng smock',
    extraction_model_used: response.model || 'unknown',
    extraction_ok: !apiError && !!parsed,
    extraction_error: apiError || (parsed ? null : 'Model response was not valid JSON')
  }
};

const execution = $json;
const workflow = execution.workflowData ?? execution.workflow ?? {};
const runData = execution.data?.resultData?.runData ?? {};
const connections = workflow.connections ?? {};

function clone(v) {
  try { return JSON.parse(JSON.stringify(v)); } catch { return v; }
}

function outputsOf(nodeName) {
  const runs = runData[nodeName] ?? [];
  return runs.map((run, runIndex) => ({
    runIndex,
    output: clone(run?.data?.main ?? [])
  }));
}

function upstream(nodeName) {
  const result = [];
  for (const [sourceName, conn] of Object.entries(connections)) {
    const groups = conn?.main ?? [];
    for (let outputIndex = 0; outputIndex < groups.length; outputIndex++) {
      for (const target of (groups[outputIndex] ?? [])) {
        if (target.node === nodeName) {
          result.push({
            fromNode: sourceName,
            fromOutputIndex: outputIndex,
            data: outputsOf(sourceName)
          });
        }
      }
    }
  }
  return result;
}

const nodeNames = Object.keys(runData);
const report = {
  execution: {
    id: execution.id ?? null,
    status: execution.status ?? null,
    startedAt: execution.startedAt ?? null,
    stoppedAt: execution.stoppedAt ?? null,
    workflowId: execution.workflowData?.id ?? execution.workflowId ?? null,
    workflowName: execution.workflowData?.name ?? execution.workflowData?.meta?.name ?? null,
  },
  nodes: nodeNames.map((name, index) => ({
    order: index + 1,
    node: name,
    input_reconstructed_from_upstream_outputs: upstream(name),
    output: outputsOf(name),
    note: "Input is reconstructed from the execution outputs of nodes connected upstream. n8n execution storage primarily records runData/output; the UI derives displayed input from upstream execution data."
  }))
};

return [{json: report}];
